## Diff
````diff
diff --git a/apps/console/src/features/projects/screens/charter-essentials-fields.tsx b/apps/console/src/features/projects/screens/charter-essentials-fields.tsx
--- /dev/null
+++ b/apps/console/src/features/projects/screens/charter-essentials-fields.tsx
L1: +/**
L2: + * The two fields a project really needs — name and outcome — plus the two
L3: + * the server requires but the operator should not have to look up: the key
L4: + * prefix (derived from the name until they edit it) and the lead (the signed-
L5: + * in user until they change it). Everything else the design's charter
L6: + * captures lives behind `charter-detail-fields.tsx`'s disclosure
L7: + * (`docs/toolu/specs/2026-09-20-agent-native-project-management-design.md`
L8: + * § Console information architecture).
L9: + *
L10: + * Every field here is a `form.Field` on the parent's own form instance, so
L11: + * the names are checked against `CharterFormSchema` and the notes under the
L12: + * controls are the schema's own messages.
L13: + */
L14: +
L15: +import { SchemaTextareaField, SchemaTextField } from '@/ui/components/schema-fields';
L16: +
L17: +import {
L18: +  CHARTER_KEY_PREFIX_MAX,
L19: +  CHARTER_NAME_MAX,
L20: +  CHARTER_OUTCOME_MAX,
L21: +  deriveKeyPrefix,
L22: +} from './charter-form-rules';
L23: +import type { CharterForm } from './use-charter-form';
L24: +
L25: +/** How the lead is chosen — the session's user, or an id the operator typed. */
L26: +type LeadFieldState = {
L27: +  /** How to name the signed-in user; `undefined` until the session is read. */
L28: +  sessionLabel: string | undefined;
L29: +  /** True once the operator chose to type an id instead of keeping themselves. */
L30: +  overriding: boolean;
L31: +  onOverride: () => void;
L32: +  onRestoreSelf: () => void;
L33: +};
L34: +
L35: +/** Props for `CharterEssentialsFields`. */
L36: +type CharterEssentialsFieldsProps = {
L37: +  form: CharterForm;
L38: +  lead: LeadFieldState;
L39: +  /** False once the operator edits the prefix — the name stops filling it then. */
L40: +  keyPrefixAuto: boolean;
L41: +  onKeyPrefixEdited: () => void;
L42: +};
L43: +
L44: +/** The lead as a fact the operator can change, rather than an id they must find. */
L45: +function CharterLeadField({ form, lead }: { form: CharterForm; lead: LeadFieldState }) {
L46: +  if (lead.sessionLabel !== undefined && !lead.overriding) {
L47: +    return (
L48: +      <div className="flex flex-col gap-1">
L49: +        <span className="type-label text-ink-muted">lead</span>
L50: +        <div className="h-field-app flex items-center justify-between gap-3 rounded-sm border border-border bg-surface-inset px-3">
L51: +          <span className="type-body-sm truncate text-ink">{lead.sessionLabel} · you</span>
L52: +          <button
L53: +            type="button"
L54: +            onClick={lead.onOverride}
L55: +            className="type-button transition-hover flex-none text-ink-muted"
L56: +          >
L57: +            Change
L58: +          </button>
L59: +        </div>
L60: +        <p className="type-meta text-ink-muted">Whoever owns this charter's decisions.</p>
L61: +      </div>
L62: +    );
L63: +  }
L64: +  return (
L65: +    <div className="flex flex-col gap-1">
L66: +      <form.Field name="leadUserId">
L67: +        {(field) => (
L68: +          <SchemaTextField
L69: +            field={field}
L70: +            label="lead (workspace member id)"
L71: +            fieldId="charter-lead"
L72: +            aria-required
L73: +          />
L74: +        )}
L75: +      </form.Field>
L76: +      {lead.sessionLabel !== undefined && (
L77: +        <button
L78: +          type="button"
L79: +          onClick={lead.onRestoreSelf}
L80: +          className="type-button transition-hover self-start text-ink-muted"
L81: +        >
L82: +          Lead it myself
L83: +        </button>
L84: +      )}
L85: +    </div>
L86: +  );
L87: +}
L88: +
L89: +/** Name, outcome, key prefix, lead — the only fields on screen before the disclosure. */
L90: +export function CharterEssentialsFields({
L91: +  form,
L92: +  lead,
L93: +  keyPrefixAuto,
L94: +  onKeyPrefixEdited,
L95: +}: CharterEssentialsFieldsProps) {
L96: +  return (
L97: +    <div className="flex flex-col gap-4">
L98: +      <form.Field name="name">
L99: +        {(field) => (
L100: +          <SchemaTextField
L101: +            field={field}
L102: +            label="name"
L103: +            fieldId="charter-name"
L104: +            aria-required
L105: +            maxLength={CHARTER_NAME_MAX}
L106: +            onChange={(event) => {
L107: +              field.handleChange(event.target.value);
L108: +              if (keyPrefixAuto) {
L109: +                form.setFieldValue('keyPrefix', deriveKeyPrefix(event.target.value));
L110: +              }
L111: +            }}
L112: +          />
L113: +        )}
L114: +      </form.Field>
L115: +      <form.Field name="outcome">
L116: +        {(field) => (
L117: +          <SchemaTextareaField
L118: +            field={field}
L119: +            label="outcome"
L120: +            fieldId="charter-outcome"
L121: +            aria-required
L122: +            maxLength={CHARTER_OUTCOME_MAX}
L123: +            hint="What is true once this project is done — one or two sentences."
L124: +          />
L125: +        )}
L126: +      </form.Field>
L127: +      <div className="grid gap-4 lg:grid-cols-2">
L128: +        <form.Field name="keyPrefix">
L129: +          {(field) => (
L130: +            <SchemaTextField
L131: +              field={field}
L132: +              label="key prefix"
L133: +              fieldId="charter-key-prefix"
L134: +              aria-required
L135: +              maxLength={CHARTER_KEY_PREFIX_MAX}
L136: +              hint={
L137: +                keyPrefixAuto
L138: +                  ? 'Derived from the name — type to override.'
L139: +                  : 'Uppercase letters/digits, starting with a letter.'
L140: +              }
L141: +              onChange={(event) => {
L142: +                onKeyPrefixEdited();
L143: +                field.handleChange(event.target.value.toUpperCase());
L144: +              }}
L145: +            />
L146: +          )}
L147: +        </form.Field>
L148: +        <CharterLeadField form={form} lead={lead} />
L149: +      </div>
L150: +    </div>
L151: +  );
L152: +}
````

